import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Wallet wallet = new Wallet();
        for(int i = 0; i < n; i++) {
            String op = sc.next();
            if(op.equals("D")) {
                wallet.deposit(sc.nextDouble());
            } else if(op.equals("W")) {
                wallet.withdraw(sc.nextDouble());
            } else {
                wallet.printBalance();
            }
        }
        System.out.printf("Final: %.2f%n", wallet.getBalance());
    }
}

class Wallet {
    private double balance;

    void deposit(double amount) {
        balance = balance + amount;
    }

    void withdraw(double amount) {
        if(amount <= balance) {
            balance = balance - amount;
        } else {
            System.out.println("Insufficient funds");
        }
    }

    void printBalance() {
        System.out.printf("Balance: %.2f%n", balance);
    }

    double getBalance() {
        return balance;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String name = sc.next();
        int marks = sc.nextInt();
        Student student = new Student();
        student.setMarks(marks);
        System.out.println(name + " got grade " + student.grade());
    }
}

class Student {
    private int marks;

    void setMarks(int m) {
        marks = m;
    }

    char grade() {
        if(marks >= 90) {
            return 'A';
        } else if(marks >= 75) {
            return 'B';
        } else if(marks >= 60) {
            return 'C';
        } else if(marks >= 40) {
            return 'D';
        }
        return 'F';
    }
}

