            double value = items[i].stockValue();
            total = total + value;
            System.out.printf("%s %.2f%n", items[i].name, value);
        }
        System.out.printf("Total: %.2f%n", total);
    }
}

class Product {
    String name;
    int quantity;
    double price;

    double stockValue() {
        return quantity * price;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Car[] fleet = new Car[n];
        for(int i = 0; i < n; i++) {
            fleet[i] = new Car();
            int m = sc.nextInt();
            for(int j = 0; j < m; j++) {
                fleet[i].trip(sc.nextInt(), sc.nextDouble());
            }
        }
        int totalKm = 0;
        double totalFuel = 0;
        for(int i = 0; i < n; i++) {
            fleet[i].report(i + 1);
            totalKm = totalKm + fleet[i].getDistance();
            totalFuel = totalFuel + fleet[i].getFuelUsed();
        }
        System.out.printf("Fleet: %d km, %.2f km/l%n", totalKm, totalKm / totalFuel);
    }
}

class Car {
    private int distance;
    private double fuelUsed;

    void trip(int km, double litres) {
        distance = distance + km;
        fuelUsed = fuelUsed + litres;
    }

    int getDistance() {
        return distance;
    }

    double getFuelUsed() {
        return fuelUsed;
    }

    double average() {
        if(distance == 0) {
            return 0.0;
        }
        return distance / fuelUsed;
    }

    void report(int number) {
        System.out.printf("Car %d: %d km, %.2f km/l%n", number, distance, average());
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        BankAccount acc = new BankAccount();
        for(int i = 0; i < n; i++) {
            String op = sc.next();
            double amount = sc.nextDouble();
            if(op.equals("D")) {
                acc.deposit(amount);
            } else {
                acc.withdraw(amount);
            }
        }
        acc.printSummary();
    }
}

class BankAccount {
    private double balance;
    private int transactions;
    private double deposited;
    private double withdrawn;

    void deposit(double amount) {
        balance = balance + amount;
        deposited = deposited + amount;
        transactions++;
    }

    void withdraw(double amount) {
        if(amount <= balance) {
            balance = balance - amount;
            withdrawn = withdrawn + amount;
            transactions++;
        } else {
            System.out.println("Rejected");
        }
    }

    void printSummary() {
        System.out.printf("Balance: %.2f%n", balance);
        System.out.println("Transactions: " + transactions);
        System.out.printf("Deposited: %.2f%n", deposited);
        System.out.printf("Withdrawn: %.2f%n", withdrawn);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Patient[] ward = new Patient[n];
        int size = 0;
        int discharged = 0;
        for(int i = 0; i < n; i++) {
            String action = sc.next();
            if(action.equals("admit")) {
                Patient p = new Patient();
                p.setName(sc.next());
                p.setAge(sc.nextInt());
                ward[size] = p;
                size++;
            } else {
                String who = sc.next();
                for(int j = 0; j < size; j++) {
                    if(ward[j].getName().equals(who) && ward[j].isAdmitted()) {
                        ward[j].setAdmitted(false);
                        discharged++;
                        break;
                    }
                }
            }
        }
        int stillIn = 0;
        int oldestAge = -1;
        String oldestName = "None";
        for(int j = 0; j < size; j++) {
            if(ward[j].isAdmitted()) {
                stillIn++;
                if(ward[j].getAge() > oldestAge) {
                    oldestAge = ward[j].getAge();
                    oldestName = ward[j].getName();
                }
            }
        }
        System.out.println("Admitted: " + size);
        System.out.println("Discharged: " + discharged);
        System.out.println("Still in ward: " + stillIn);
        if(stillIn == 0) {
            System.out.println("Oldest: None");
        } else {
            System.out.println("Oldest: " + oldestName + " (" + oldestAge + ")");
        }
    }
}

class Patient {
    private String name;
    private int age;
    private boolean admitted;

    void setName(String n) {
        name = n;
        admitted = true;
    }

    void setAge(int a) {
        age = a;
    }

    void setAdmitted(boolean value) {
        admitted = value;
    }

    String getName() {
        return name;
    }

    int getAge() {
        return age;
    }

    boolean isAdmitted() {
        return admitted;
    }
}
